import * as React from 'react';
import { LineChart } from '@mui/x-charts/LineChart';

export default function DiceLineChartComponent({ history, diceStyles, totalRolls }) {
    // Create x-axis data of length 10, starting from 0 and ending at headsHistory.length
    const generateRandomXAxis = (count, flipCount) => {
        // Calculate the step size for even spacing
        const step = Math.floor(flipCount / (count - 1)); // -1 to leave space for the last value (flipCount)

        // Create an array of evenly spaced values
        const result = Array.from({ length: count - 1 }, (_, i) => i * step);

        // Ensure the last value is exactly flipCount
        result.push(flipCount);

        return result;
    };

    // Usage
    const xAxis = generateRandomXAxis(totalRolls < 10 ? (totalRolls + 1) : 10, totalRolls);

    // Generate new heads and tails data for the chart based on xAxis indices
    const data1 = xAxis.map(index => (history.History1[index * diceStyles.length]) || 0);
    const data2 = xAxis.map(index => (history.History2[index * diceStyles.length]) || 0);
    const data3 = xAxis.map(index => (history.History3[index * diceStyles.length]) || 0);
    const data4 = xAxis.map(index => (history.History4[index * diceStyles.length]) || 0);
    const data5 = xAxis.map(index => (history.History5[index * diceStyles.length]) || 0);
    const data6 = xAxis.map(index => (history.History6[index * diceStyles.length]) || 0);

    return (
        <LineChart
            xAxis={[{ data: xAxis }]}  // Use the new xAxis array
            series={[
                {
                    data: data1, // Data for the first line (heads)
                    label: 'Mặt 1', // Label for the first line
                },
                {
                    data: data2, // Data for the second line (tails)
                    label: 'Mặt 2', // Label for the second line
                },
                {
                    data: data3, // Data for the second line (tails)
                    label: 'Mặt 3', // Label for the second line
                },
                {
                    data: data4, // Data for the second line (tails)
                    label: 'Mặt 4', // Label for the second line
                    color: '#c0bbbb',
                },
                {
                    data: data5, // Data for the second line (tails)
                    label: 'Mặt 5', // Label for the second line
                },
                {
                    data: data6, // Data for the second line (tails)
                    label: 'Mặt 6', // Label for the second line
                    color: '#ffd700',
                },
            ]}
            width={500}
            height={300}
        />
    );
}
