import React, { useEffect, useState } from "react";
import { Button, TextField, Box, Grid, Typography, List, ListItem, ListItemText } from "@mui/material";
import "./dice_roller.css";
import PieChartComponent from "src/components/chart/PieChart";
import DiceBarChartComponent from "src/components/chart/DiceBarChart";
import DiceLineChartComponent from "src/components/chart/DiceLineChart";

const DiceRoller = () => {
    const [diceStyles, setDiceStyles] = useState(["rotateX(0deg) rotateY(0deg)"]);
    const [isRolling, setIsRolling] = useState(false);
    const [rollCounts, setRollCounts] = useState([0, 0, 0, 0, 0, 0]);
    const [totalRolls, setTotalRolls] = useState(0);
    const [rollTimes, setRollTimes] = useState(1);
    const [history, setHistory] = useState({
        History1: [0],
        History2: [0],
        History3: [0],
        History4: [0],
        History5: [0],
        History6: [0]
    });
    const [totalHistory, setTotalHistory] = useState([]);
    const handleAddToHistory = (value) => {
        setTotalHistory(prevHistory => [...prevHistory, value]);
    };
    console.log('totalHistory', totalHistory);

    const randomDice = () => {
        // Tạo các giá trị ngẫu nhiên cho các viên xúc xắc
        const randomValues = Array.from({ length: diceStyles.length }, () =>
            Math.floor(Math.random() * 6) + 1
        );
        randomValues.forEach(value => {

            handleAddToHistory(value)
        });
        // Sắp xếp randomValues theo thứ tự tăng dần
        const sortedRandomValues = [...randomValues].sort((a, b) => a - b);
        // Cập nhật history dựa trên các giá trị ngẫu nhiên đã sắp xếp
        setHistory(prevHistory => {
            const updatedHistory = { ...prevHistory };
            // Duyệt qua các giá trị trong sortedRandomValues
            sortedRandomValues.forEach(value => {
                const historyKey = `History${value}`; // Tạo key tương ứng như History1, History2, History3...
                updatedHistory[historyKey].push(updatedHistory[historyKey][updatedHistory[historyKey].length - 1] + 1);

            });
            // Lưu lại lịch sử của các mặt, thay vì thêm 0 nếu mặt không xuất hiện, sẽ thêm giá trị cuối cùng của lịch sử đó
            for (let i = 1; i <= 6; i++) {
                const historyKey = `History${i}`;
                sortedRandomValues.forEach(value => {
                    if (i !== value) {
                        // Nếu không có trong sortedRandomValues, thay vì thêm 0, thêm giá trị cuối cùng của mảng history hiện tại
                        const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;
                        updatedHistory[historyKey].push(lastValue); // Thêm giá trị cuối cùng của lịch sử vào
                    }
                });

            }

            return updatedHistory;
        });

        // Gọi hàm rollDice với các giá trị ngẫu nhiên đã sắp xếp
        rollDice(sortedRandomValues);
    };

    const rollDice = (randomValues) => {
        const rotationMap = {
            1: "rotateX(0deg) rotateY(0deg)",
            2: "rotateX(-90deg) rotateY(0deg)",
            3: "rotateX(0deg) rotateY(90deg)",
            4: "rotateX(0deg) rotateY(-90deg)",
            5: "rotateX(90deg) rotateY(0deg)",
            6: "rotateX(180deg) rotateY(0deg)",
        };

        setTotalRolls(prev => prev + 1);
        setIsRolling(true);
        setTimeout(() => {
            setDiceStyles(randomValues.map((value) => rotationMap[value]));
            const newRollCounts = [...rollCounts];

            randomValues.forEach(value => {
                newRollCounts[value - 1] += 1;
            });
            setRollCounts(newRollCounts);
            setIsRolling(false);
        }, 2050);
    };

    const addDice = () => {
        if (diceStyles.length < 6) {
            setDiceStyles([...diceStyles, "rotateX(0deg) rotateY(0deg)"]);
            setRollCounts([0, 0, 0, 0, 0, 0]);
            setTotalRolls(0);
            setRollTimes(1);
        }
    };

    const removeDice = () => {
        if (diceStyles.length > 0) {
            setDiceStyles(diceStyles.slice(0, -1));
            setRollCounts([0, 0, 0, 0, 0, 0]);
            setTotalRolls(0);
            setRollTimes(1);
        }
    };

    const renderDice = (styles, start, end) => (
        <div className="dice-row">
            {styles.slice(start, end).map((style, index) => (
                <div
                    key={start + index}
                    className={`dice ${isRolling ? "rolling" : ""}`}
                    style={{
                        transform: style,
                        marginRight: "25px",
                        marginBottom: "30px",
                    }}
                >
                    <div className="face front"></div>
                    <div className="face back"></div>
                    <div className="face top"></div>
                    <div className="face bottom"></div>
                    <div className="face right"></div>
                    <div className="face left"></div>
                </div>
            ))}
        </div>
    );

    const handleRollMultipleTimes = () => {
        setIsRolling(true);
        setTotalRolls(0);
        setTotalHistory([])

        const newRollCounts = [0, 0, 0, 0, 0, 0];
        // Lưu lại lịch sử trước khi bắt đầu
        const updatedHistory = {
            History1: [0],
            History2: [0],
            History3: [0],
            History4: [0],
            History5: [0],
            History6: [0]
        };  // Giả sử 'history' là đối tượng lưu lịch sử

        for (let i = 0; i < rollTimes; i++) {
            // Tạo các giá trị ngẫu nhiên cho các viên xúc xắc
            const randomValues = Array.from({ length: diceStyles.length }, () =>
                Math.floor(Math.random() * 6) + 1
            );
            // Cập nhật số lần xuất hiện của mỗi mặt
            randomValues.forEach(value => {
                newRollCounts[value - 1] += 1;
            });

            // Sắp xếp randomValues theo thứ tự tăng dần
            const sortedRandomValues = [...randomValues].sort((a, b) => a - b);
            // Lưu lại lịch sử của các mặt, thay vì thêm 0 nếu mặt không xuất hiện, sẽ thêm giá trị cuối cùng của lịch sử đó
            for (let i = 1; i <= 6; i++) {
                const historyKey = `History${i}`;
                sortedRandomValues.forEach(value => {
                    if (i !== value) {
                        // Nếu không có trong sortedRandomValues, thay vì thêm 0, thêm giá trị cuối cùng của mảng history hiện tại
                        const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;

                        updatedHistory[historyKey].push(lastValue); // Thêm giá trị cuối cùng của lịch sử vào
                    }
                });

            }
            // Cập nhật lịch sử dựa trên các giá trị ngẫu nhiên đã sắp xếp
            sortedRandomValues.forEach(value => {
                const historyKey = `History${value}`; // Tạo key tương ứng như History1, History2, History3...
                updatedHistory[historyKey].push(updatedHistory[historyKey][updatedHistory[historyKey].length - 1] + 1);
                handleAddToHistory(value)
            });


            // Cập nhật lại lịch sử sau mỗi lần lắc


            // Gọi hàm rollDice với các giá trị ngẫu nhiên đã sắp xếp
            const rotationMap = {
                1: "rotateX(0deg) rotateY(0deg)",
                2: "rotateX(-90deg) rotateY(0deg)",
                3: "rotateX(0deg) rotateY(90deg)",
                4: "rotateX(0deg) rotateY(-90deg)",
                5: "rotateX(90deg) rotateY(0deg)",
                6: "rotateX(180deg) rotateY(0deg)",
            };

            setDiceStyles(randomValues.map(value => rotationMap[value]));
            setRollCounts(newRollCounts);
        }

        // Sau khi hết tất cả các lần lắc, cập nhật tổng số lần lắc
        setTimeout(() => {
            setIsRolling(false);
            setTotalRolls(prev => prev + rollTimes);
        }, 2050);
        setHistory(updatedHistory);
    };


    const reset = () => {
        setDiceStyles(["rotateX(0deg) rotateY(0deg)"]);
        setRollCounts([0, 0, 0, 0, 0, 0]);
        setTotalRolls(0);
        setRollTimes(1);
        setTotalHistory([])
    };
    const [dataPieChart, setDataPieChart] = useState([
        { id: 0, value: 0, label: 'Mặt 1', color: '#02b2af' },
        { id: 1, value: 0, label: 'Mặt 2' },
        { id: 2, value: 0, label: 'Mặt 3' },
        { id: 3, value: 0, label: 'Mặt 4', color: '#c0bbbb' },
        { id: 4, value: 0, label: 'Mặt 5' },
        { id: 5, value: 0, label: 'Mặt 6', color: '#c28215' },
    ]);

    useEffect(() => {
        // Cập nhật giá trị phần trăm khi số lần lắc thay đổi
        const total = rollCounts.reduce((sum, count) => sum + count, 0);
        const updatedData = dataPieChart.map((item, index) => {
            const value = total > 0 ? ((rollCounts[index] / total) * 100).toFixed(2) : 0;
            return { ...item, value: Number(value) };
        });
        setDataPieChart(updatedData);
    }, [rollCounts]);
    const calculateAverageProbability = (history) => {
        // Tính tần suất xuất hiện của mỗi giá trị trong totalHistory
        const frequency = history.reduce((acc, value) => {
            acc[value] = (acc[value] || 0) + 1;
            return acc;
        }, {});

        // Tính tổng tần suất
        const totalCount = Object.values(frequency).reduce((sum, count) => sum + count, 0);

        // Tính tổng giá trị (giá trị mặt xúc xắc * tần suất)
        const weightedSum = Object.keys(frequency).reduce((sum, key) => {
            const value = Number(key); // Chuyển key về dạng số
            const count = frequency[key];
            return sum + (value * count);
        }, 0);

        // Tính số trung bình xác suất có tần suất
        return totalCount > 0 ? weightedSum / totalCount : 0;
    };
    function calculateMedian(arr) {
        // Tạo một mảng mới sao chép từ mảng gốc
        const newArr = [...arr]; // Hoặc có thể dùng const newArr = arr.slice();

        // Sắp xếp mảng sao chép
        newArr.sort((a, b) => a - b);

        const length = newArr.length;

        // Nếu mảng có số phần tử lẻ, trả về phần tử ở giữa
        if (length % 2 !== 0) {
            return newArr[Math.floor(length / 2)];
        }

        // Nếu mảng có số phần tử chẵn, trả về trung bình của hai phần tử ở giữa
        const mid1 = newArr[length / 2 - 1];
        const mid2 = newArr[length / 2];
        const median = (mid1 + mid2) / 2;

        // Nếu kết quả là NaN, trả về 0
        return isNaN(median) ? 0 : median;
    }

    const averageProbability = calculateAverageProbability(totalHistory);
    const median = calculateMedian(totalHistory)
    // Hàm tính mốt
    function calculateMode(arr) {
        const frequency = {}; // Đối tượng lưu tần suất xuất hiện của các phần tử trong mảng
        let maxFreq = 0; // Tần suất lớn nhất
        let mode = []; // Mảng chứa các số mốt
        // Đếm số lần xuất hiện của từng phần tử trong mảng
        for (let i = 0; i < arr.length; i++) {
            const num = arr[i];
            frequency[num] = (frequency[num] || 0) + 1;
            if (frequency[num] > maxFreq) {
                maxFreq = frequency[num];
                mode = [num]; // Nếu có tần suất cao hơn, reset mảng mode
            } else if (frequency[num] === maxFreq) {
                mode.push(num); // Nếu có tần suất bằng nhau, thêm vào mảng mode
            }
        }
        return mode;
    }
    const mode = calculateMode(totalHistory);

    return (
        <>
            <Grid container spacing={2} direction="column"
                alignItems="center"
                justifyContent="center">
                <Grid item xs={12}>
                    <Typography variant="h3" fontWeight="bold" sx={{ mb: 2 }}>
                        Minh họa bài toán xúc xắc
                    </Typography>
                    <div className="container">
                        <div className="dice-container">
                            {renderDice(diceStyles, 0, 1)}
                            {renderDice(diceStyles, 1, 3)}
                            {renderDice(diceStyles, 3, 6)}
                        </div>
                        <div className="controls">
                            <Button
                                variant="contained"
                                color="primary"
                                onClick={randomDice}
                                disabled={isRolling}
                            >
                                {isRolling ? "Đang lắc..." : "Lắc"}
                            </Button>
                            <Button
                                variant="contained"
                                color="secondary"
                                onClick={addDice}
                                disabled={isRolling}
                                sx={{ ml: 2 }}
                            >
                                Thêm
                            </Button>
                            <Button
                                variant="contained"
                                color="error"
                                onClick={removeDice}
                                disabled={isRolling || diceStyles.length === 0}
                                sx={{ ml: 2 }}
                            >
                                Xóa
                            </Button>
                            <Button
                                variant="contained"
                                color="info"
                                onClick={reset}
                                disabled={isRolling}
                                sx={{ ml: 2 }}
                            >
                                Làm mới
                            </Button>
                        </div>

                        <Box sx={{ mt: 3 }}>
                            <TextField
                                type="number"
                                min="1"
                                value={rollTimes}
                                onChange={(e) => setRollTimes(Number(e.target.value))}
                                disabled={isRolling}
                                variant="outlined"
                                size="small"
                            />
                            <Button
                                variant="contained"
                                color="success"
                                onClick={handleRollMultipleTimes}
                                disabled={isRolling}
                                sx={{ ml: 2 }}
                            >
                                Xác nhận
                            </Button>
                        </Box>
                        <Box sx={{ pl: 4 }} className="roll-summary">
                            <Typography variant="h6" sx={{ mt: 2 }}>Số lần xuất hiện của mỗi mặt:</Typography>
                            <List>
                                <Grid container spacing={2}>
                                    {rollCounts.map((count, index) => (
                                        <Grid item xs={6} key={index}>
                                            <ListItem>
                                                <ListItemText
                                                    primary={`Mặt ${index + 1}: ${count} (${dataPieChart[index]?.value}%)`}
                                                />
                                            </ListItem>
                                        </Grid>
                                    ))}
                                </Grid>
                            </List>
                            <Typography variant="h6">Tổng số lần lắc: {totalRolls}</Typography>
                            <Typography variant="h6">
                                Kết quả:
                            </Typography>
                            <Typography variant="h6">
                                {'['}
                                {totalHistory.map((item, index) => (
                                    <>
                                        {item}
                                        {/* Kiểm tra nếu không phải phần tử cuối cùng thì thêm dấu ',' */}
                                        {(index + 1) !== totalHistory.length && ','}
                                        {/* Thêm thẻ <br /> sau mỗi 20 phần tử */}
                                        {(index + 1) % 20 === 0 && <br />}
                                    </>
                                ))}
                                {']'}
                            </Typography>
                            <Typography variant="h6">Số trung bình: {averageProbability.toFixed(2)}</Typography>
                            <Typography variant="h6">Số trung vị: {median}</Typography>
                            <Typography variant="h6">Mốt: {Array.isArray(mode) ? mode.join(', ') : mode}</Typography>

                        </Box>
                    </div>
                </Grid>
            </Grid>
            <Grid container spacing={2} sx={{ pl: 5 }} >
                <Grid item xs={12}>
                    <Typography variant="h3" fontWeight="bold" sx={{ mb: 2 }}>
                        Biểu đồ
                    </Typography>
                    <Grid container spacing={2} sx={{ mt: 2 }}>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6' sx={{ mb: 4 }}>Biểu đồ quạt</Typography>
                            <PieChartComponent data={dataPieChart} width={400} height={200} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6'>Biểu đồ cột</Typography>
                            <DiceBarChartComponent dataBarChart={rollCounts} width={400} height={200} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={12}>
                            <Typography variant='h6' sx={{ mb: 4 }}>Biểu đồ đoạn thằng</Typography>
                            <DiceLineChartComponent history={history} diceStyles={diceStyles} totalRolls={totalRolls} />
                        </Grid>
                    </Grid>
                </Grid>
            </Grid>
        </>
    );
};

export default DiceRoller;
