import * as React from 'react';
import { BarChart } from '@mui/x-charts/BarChart';

export default function DiceBarChartComponent({ dataBarChart }) {
    return (
        <BarChart
            xAxis={[{
                scaleType: 'band', data: ['Mặt 1', 'Mặt 2', 'Mặt 3', 'Mặt 4', 'Mặt 5', 'Mặt 6'], colorMap: {
                    type: "ordinal",
                    colors: ['#02b2af', '#2e96ff', '#b800d8', '#c0bbbb', '#2731c8', '#c28215'],
                },
            }]}
            series={[
                {
                    data: dataBarChart, // Values for heads and tails

                },

            ]}
            width={500}
            height={300}
        />
    );
}